"""Generate our original rectangle glyph fixture with fontTools (test tooling only)."""
from fontTools.fontBuilder import FontBuilder
from fontTools.pens.ttGlyphPen import TTGlyphPen
from io import BytesIO
from pathlib import Path
import base64
fb=FontBuilder(1000,isTTF=True)
fb.setupGlyphOrder(['.notdef','space','block'])
glyphs={}
for name in ['.notdef','space','block']:
    pen=TTGlyphPen(None)
    if name=='block':
        pen.moveTo((80,0));pen.lineTo((520,0));pen.lineTo((520,700));pen.lineTo((80,700));pen.closePath()
    glyphs[name]=pen.glyph()
fb.setupGlyf(glyphs)
fb.setupHorizontalMetrics({n:(600,0) for n in glyphs})
fb.setupHorizontalHeader(ascent=800,descent=-200)
fb.setupCharacterMap({**{n:'block' for n in range(33,127)},32:'space'})
fb.setupNameTable({'familyName':'Comins Fixture','styleName':'Regular','uniqueFontIdentifier':'CominsFixture1','fullName':'Comins Fixture Regular','psName':'CominsFixture-Regular','version':'Version 1.0'})
fb.setupOS2(sTypoAscender=800,sTypoDescender=-200,usWinAscent=800,usWinDescent=200)
fb.setupPost();fb.setupMaxp()
fb.font['head'].created=fb.font['head'].modified=3400000000
out=BytesIO();fb.save(out)
Path('test/browser/font-fixture.mjs').write_text('// Original rectangle glyph fixture; MIT. Generated by test/fixtures/create-font.py.\nexport const fontData="data:font/ttf;base64,'+base64.b64encode(out.getvalue()).decode()+'";\n')
